svg('fraction-beyond-one','Fractions are numbers beyond one whole','<path d="M70 170H730" stroke="#163f36" stroke-width="3"/>'+''.join(f'<path d="M{70+i*55} 158v24" stroke="#163f36"/>' for i in range(13))+''.join(f'<text x="{70+i*55}" y="213" text-anchor="middle" font-size="17">{label}</text>' for i,label in [(0,'0'),(3,'1/2'),(6,'1'),(9,'3/2'),(12,'2')])+'<circle cx="565" cy="170" r="9" fill="#bb5538"/><text x="390" y="105" font-size="24">9/6 = 3/2 = 1 + 1/2</text><text x="40" y="296" font-size="20">Each small interval is one sixth of the same unit.</text>')
